336:     std::byte* buffer, std::size_t size) {
337:     if (!stream) {
338:       throw std::runtime_error("Stream is not valid for reading");
339:     }
340:     struct SeekGuard {
341:       std::istream& stream;
342:       std::streampos oldPos;
343:       SeekGuard(std::istream& s, std::streampos p) : stream(s), oldPos(s.tellg()) {
344:         stream.seekg(p);
345:       }
346:       ~SeekGuard() {
347:         stream.seekg(oldPos);
348:       }
349:     } seekGuard(stream, pos);
350:     if (!stream) {
351:       throw std::runtime_error("Failed to seek to position in stream");
352:     }
353:     stream.read(reinterpret_cast<char*>(buffer), size);
354:     if (!stream || static_cast<std::size_t>(stream.gcount()) != size) {
355:       throw std::runtime_error("Failed to read the requested number of bytes from the stream");
356:     }
357:     return stream;
