685:     static ImageData readImageStrips(std::istream& stream, const IFD& ifd) {
686:       const auto& entries = ifd.entries();
687:       std::vector<uint32_t> stripOffsets, stripByteCounts;
688:       { //copy offsets
689:         const auto& entry = ifd.getEntry(Tag::StripOffsets, "StripOffsets entry not found in IFD");
690:         copyVector<uint32_t>(entry.type(), entry.values(), entry.count(), stripOffsets);
691:       }
692:       { //copy byte counts
693:         const auto& entry = ifd.getEntry(Tag::StripByteCounts, "StripByteCounts entry not found in IFD");
694:         copyVector<uint32_t>(entry.type(), entry.values(), entry.count(), stripByteCounts);
695:       }
696:       if (stripOffsets.size() != stripByteCounts.size()) {
697:         throw std::runtime_error("Mismatch between number of StripOffsets and StripByteCounts");
698:       }
699:       ImageData imageData;
700:       for (size_t i = 0; i < stripOffsets.size(); ++i) {
701:         const uint32_t offset = stripOffsets[i];
702:         const uint32_t byteCount = stripByteCounts[i];
703:         if (offset < 8 || byteCount == 0) {
704:           throw std::runtime_error("Invalid strip offset or byte count");
705:         }
706:         imageData.emplace_back(byteCount);
707:         readAt(stream, offset, imageData.back().data(), byteCount);
708:       }
709:       return imageData;
710:     }
