512: TEST_CASE("TiffExporterAny multi-IFD export") {
513:   // Synthesize a 2-IFD 8-bit grayscale TIFF in-memory:
514:   //   IFD1 at offset 8,   strip pixels at offset 122 (10, 20, 30, 40)
515:   //   IFD2 at offset 126, strip pixels at offset 240 (200, 210, 220, 230)
516:   constexpr uint32_t W = 2, H = 2;
517:   constexpr uint32_t ifdSize = 2 + 9 * 12 + 4; // 2-byte count, 9 entries, 4-byte next IFD offset
518:   constexpr uint32_t ifd1Offset = 8;
519:   constexpr uint32_t pix1Offset = ifd1Offset + ifdSize; // 122
520:   constexpr uint32_t ifd2Offset = pix1Offset + 4;       // 126
521:   constexpr uint32_t pix2Offset = ifd2Offset + ifdSize; // 240
522: 
523:   const std::vector<std::byte> pix1{ std::byte{10}, std::byte{20}, std::byte{30}, std::byte{40} };
524:   const std::vector<std::byte> pix2{ std::byte{200}, std::byte{210}, std::byte{220}, std::byte{230} };
525: 
526:   std::stringstream stream;
527:   auto le16 = [&stream](uint16_t v) {
528:     const char bytes[2] = { static_cast<char>(v & 0xff), static_cast<char>((v >> 8) & 0xff) };
529:     stream.write(bytes, sizeof(bytes));
530:   };
531:   auto le32 = [&stream](uint32_t v) {
532:     const char bytes[4] = {
533:       static_cast<char>(v & 0xff), static_cast<char>((v >> 8) & 0xff),
534:       static_cast<char>((v >> 16) & 0xff), static_cast<char>((v >> 24) & 0xff)
535:     };
536:     stream.write(bytes, sizeof(bytes));
537:   };
538:   auto entry = [&le16, &le32](uint16_t tag, Type type, uint32_t count, uint32_t value) {
539:     le16(tag);
540:     le16(static_cast<uint16_t>(type));
541:     le32(count);
542:     le32(value); // Inline value, or the offset of the value for values larger than 4 bytes
543:   };
544:   auto writeIfd = [&](uint32_t pixOffset, uint32_t nextIfd) {
545:     le16(9); // 9 entries
546:     entry(256, Type::LONG, 1, W); // ImageWidth
547:     entry(257, Type::LONG, 1, H); // ImageLength
548:     entry(258, Type::SHORT, 1, 8); // BitsPerSample (inline, low 2 bytes)
549:     entry(259, Type::SHORT, 1, 1); // Compression = none
550:     entry(262, Type::SHORT, 1, 1); // PhotometricInterpretation = BlackIsZero
551:     entry(273, Type::LONG, 1, pixOffset); // StripOffsets
552:     entry(277, Type::SHORT, 1, 1); // SamplesPerPixel
553:     entry(278, Type::LONG, 1, H); // RowsPerStrip
554:     entry(279, Type::LONG, 1, 4); // StripByteCounts
555:     le32(nextIfd);
556:   };
