563:   writeIfd(pix1Offset, ifd2Offset);
564:   stream.write(reinterpret_cast<const char*>(pix1.data()), pix1.size());
565:   // IFD2 + pixels
566:   writeIfd(pix2Offset, 0);
567:   stream.write(reinterpret_cast<const char*>(pix2.data()), pix2.size());
